import {TROOPS,PHASES,BLOCKS,troop,eligible,standings,summary,rankEntries} from './domain.js';
import {configured,getSession,isDemo,login,snapshot,mutate,logout,forget,checkConnection} from './api.js';
import {openDatabaseEditor} from './admin-db.js';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
let state=null,tab='home',day='viernes',block='Todos',kitchenMeal='almuerzo',search='',busy=false,lastSync=null,timer,formDirty=false;
const KITCHEN_MEALS={almuerzo:'Almuerzo',cena:'Cena',desayuno:'Desayuno'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const PROGRAM_PAGES=35; // Actualizar si se reemplaza el programa.
const programSrc=n=>`./programa/pagina-${String(n).padStart(2,'0')}.jpg`;
const admin=()=>getSession()?.role==='admin';
const pname=id=>state.patrols.find(p=>p.id===id)?.name||'Patrulla retirada';
const gname=id=>id.startsWith('cocina-')?`Reto de cocina · ${KITCHEN_MEALS[id.slice(7)]||'sábado'}`:id.startsWith('adjustment-')?'Ajuste de puntaje':state.games.find(g=>g.id===id)?.name||id;
const adjustmentTarget=r=>r.adjustment_target_type==='patrol'?pname(r.adjustment_target):r.adjustment_target_type==='troop'?troop(r.adjustment_target)?.short||r.adjustment_target:r.adjustment_target==='europeos'?'Europeos':'Muiscas';
const resultName=r=>r.kind==='adjustment'?r.label||'Ajuste de puntaje':gname(r.game);
const date=v=>new Date(v).toLocaleString('es-BO',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',games:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',kitchen:'<path d="M8 3v8a4 4 0 0 1-4 4V3m4 0v12m4-12v7m4-7v7m-4 0h4m-2 0v11"/>',rank:'<path d="M8 3h8v7a4 4 0 0 1-8 0Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v5m-5 2h10"/>',results:'<path d="M7 3h10v3H7Z"/><path d="M7 5H4v16h16V5h-3M8 11h8m-8 4h8"/>',admin:'<path d="m12 3 8 4v6c0 4-8 8-8 8s-8-4-8-8V7Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]}</svg>`;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',5000);}
function open(html){modal.onkeydown=null;modal.classList.remove('bulk','pdf');$('#modal-body').innerHTML=html;formDirty=true;modal.showModal();$('#modal-body').querySelector('input,select,button')?.focus();}
function close(){modal.classList.remove('bulk','pdf');modal.close();formDirty=false;}
const head=title=>`<div class="modal-head"><h2>${title}</h2><button class="iconbtn" data-close aria-label="Cerrar">×</button></div>`;
const options=(xs,value)=>xs.map(([id,n])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(n)}</option>`).join('');
function loginPage(){
  clearInterval(timer);app.innerHTML=`<div class="login"><section class="login-art"><div class="brand"><img src="./icon.svg" alt="">EL DORADO<small>CADIPAS</small></div><div><div class="eyebrow">El campamento se vive en equipo</div><h1>Cada juego.<br>Cada conquista.</h1><p>Un solo lugar para registrar los resultados y seguir el camino hacia El Dorado.</p><div class="mountains"><i class="sun"></i></div></div><small>RUMBO A EL DORADO · EVALUACIÓN DEL CAMPAMENTO</small></section><section class="login-form"><div class="login-box"><div class="eyebrow">Bienvenido al equipo</div><h2>Entrar al campamento</h2><p>Tu contraseña define tu acceso. Usa tu nombre para que sepamos quién anotó cada resultado.</p>${!configured?'<div class="notice">Supabase aún no está conectado. Configúralo en config.js para guardar resultados.</div>':''}<form id="login-form"><label class="field"><span>Tu nombre</span><input name="name" required minlength="2" maxlength="60" placeholder="Ej. Branko Pereira" autocomplete="name"></label><label class="field"><span>Contraseña del equipo</span><input name="password" type="password" required autocomplete="current-password" placeholder="Contraseña de dirigente o administrador"></label><button class="btn primary full" ${!configured?'disabled':''}>Entrar al campamento →</button></form><div class="divider">Programa del campamento</div><button class="btn full" data-programa>Ver programa</button><p class="help" style="text-align:center;margin-top:18px">Dirigente · Dios &nbsp; / &nbsp; Administrador · Super dios</p></div></section></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await run(async()=>{await login(f.get('name'),f.get('password'));await boot();});};
  if(configured)$('#login-form').insertAdjacentHTML('afterend','<button class="btn small full" style="margin-top:12px" data-check-connection>Comprobar conexión</button>');
}
function viewProgram(){
  let page=1;
  open(`${head('Programa del campamento')}<div class="program-toolbar"><button class="btn small" data-program-prev disabled>← Anterior</button><label class="program-page"><span class="sr-only">Página</span><input id="program-page" type="number" min="1" max="${PROGRAM_PAGES}" value="1" inputmode="numeric" aria-label="Número de página"> <span>de ${PROGRAM_PAGES}</span></label><button class="btn small" data-program-next>Siguiente →</button></div><div class="program-view"><img id="program-image" src="${programSrc(1)}" alt="Programa del campamento, página 1" title="Toca o haz clic para ampliar"></div><p class="help" style="margin:10px 0 0">Usa los botones, las flechas del teclado o desliza para cambiar de página. Toca o haz clic en la página para ampliarla.</p>`);
  modal.classList.add('pdf');formDirty=false;
  const img=$('#program-image'),input=$('#program-page'),prev=document.querySelector('[data-program-prev]'),next=document.querySelector('[data-program-next]'),view=document.querySelector('.program-view');
  const show=n=>{page=Math.max(1,Math.min(PROGRAM_PAGES,n));img.src=programSrc(page);img.alt=`Programa del campamento, página ${page}`;input.value=page;prev.disabled=page===1;next.disabled=page===PROGRAM_PAGES;view.scrollTop=0;view.scrollLeft=0;for(const p of [page-1,page+1])if(p>=1&&p<=PROGRAM_PAGES){const pre=new Image();pre.src=programSrc(p);}};
  prev.onclick=()=>show(page-1);next.onclick=()=>show(page+1);
  img.onclick=()=>{img.classList.toggle('zoom');view.classList.toggle('zoomed',img.classList.contains('zoom'));view.scrollTop=0;view.scrollLeft=0;};
  input.onchange=()=>{const n=parseInt(input.value,10);show(Number.isFinite(n)?n:page);};
  input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();input.blur();}};
  let touchX=null,touchY=null;
  view.addEventListener('touchstart',e=>{touchX=e.touches[0]?.clientX??null;touchY=e.touches[0]?.clientY??null;},{passive:true});
  view.addEventListener('touchend',e=>{if(touchX===null||img.classList.contains('zoom')){touchX=touchY=null;return;}const dx=(e.changedTouches[0]?.clientX??touchX)-touchX,dy=(e.changedTouches[0]?.clientY??touchY)-touchY;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy))show(page+(dx<0?1:-1));touchX=touchY=null;},{passive:true});
  modal.onkeydown=e=>{if(e.target===input)return;if(e.key==='ArrowLeft'){e.preventDefault();show(page-1);}else if(e.key==='ArrowRight'){e.preventDefault();show(page+1);}};
  show(1);
}
async function boot(){try{state=await snapshot();lastSync=new Date();render();clearInterval(timer);timer=setInterval(()=>refresh(false),Math.max(10,window.CADIPAS_CONFIG?.refreshSeconds||15)*1000);}catch(e){forget();loginPage();toast(e.message);}}
async function refresh(notify=true){if(!getSession()||busy)return;try{const previous=state;state=await snapshot();lastSync=new Date();if(!modal.open&&(state!==previous||notify))render();if(notify)toast('Resultados actualizados.');}catch(e){if(notify)toast(e.message);const c=$('#sync');if(c)c.innerHTML='<span class="dot offline"></span> Sin sincronizar';}}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button[type=submit],form button:not([type])').forEach(b=>b.disabled=true);try{await fn();}catch(e){toast(e.message);}finally{busy=false;document.querySelectorAll('button[type=submit],form button:not([type])').forEach(b=>b.disabled=false);}}
async function save(action,payload){await mutate(action,payload);state=await snapshot();lastSync=new Date();close();render();toast('Guardado correctamente.');}
function nav(){return `<nav class="bottomnav" aria-label="Principal"><div class="nav-inner">${[['home','Inicio'],['games','Juegos'],['kitchen','Cocina'],['rank','Posiciones'],...(admin()?[['results','Resultados'],['admin','Control']]:[])].map(([id,label])=>`<button class="navitem ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</div></nav>`;}
function render(){
  if(!state)return loginPage();if(tab==='results'&&!admin())tab='home';const user=getSession();
  app.innerHTML=`<main class="shell"><header class="topbar"><div class="brand"><img src="./icon.svg" alt="">EL DORADO<small>CADIPAS · EVALUACIÓN</small></div><div class="session"><div><span class="badge ${admin()?'gold':''}">${admin()?'Super dios':'Dios'}</span><div class="connection" id="sync"><span class="dot ${navigator.onLine?'':'offline'}"></span>${isDemo()?'Demo local':lastSync?'Actualizado '+lastSync.toLocaleTimeString('es-BO',{hour:'2-digit',minute:'2-digit'}):'Conectando'}</div></div><span class="avatar" title="${esc(user.name)}">${esc(user.name[0]?.toUpperCase())}</span><button class="iconbtn" data-logout aria-label="Salir" title="Salir">↪</button></div></header>${isDemo()?'<div class="notice">Modo demostración · Datos de ejemplo en este dispositivo. No se comparten con otros celulares.</div>':''}${state.closed?'<div class="notice">Evento cerrado. Los resultados están bloqueados. El administrador puede reabrirlo.</div>':''}${({home:home,games:games,kitchen:kitchen,rank:rank,results:results,admin:control}[tab]||home)()}</main>${nav()}`;
  if(tab==='admin'&&admin()){const actions=app.querySelector('.actions');actions?.insertAdjacentHTML('beforeend','<button class="btn" data-tiebreak>Resolver desempates</button><button class="btn primary" data-database>Base de datos · editar todo</button>');}
  if(tab==='kitchen'){$('#kitchen-meal').onchange=e=>{kitchenMeal=e.target.value;render();};}
  if(tab==='rank'){const winner=summary(state).patrolWinner;if(winner)app.querySelector('.grid .card .section-head')?.insertAdjacentHTML('afterend',`<p class="help"><strong>Primera posición: ${esc(winner.name)}</strong></p>`);}
}
function intro(title,subtitle,action=''){return `<div class="intro"><div><div class="eyebrow">Rumbo a El Dorado</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function patrolRow(p,i){return `<div class="list-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="patrol-icon">${troop(p.troop)?.icon||'⚑'}</span><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(troop(p.troop)?.short)}</small></div><div class="value">${p.wins}<small>victorias · ${p.points} pts</small></div></div>`;}
function home(){const s=summary(state),valid=state.results.filter(r=>r.status==='validated').length,pending=state.results.filter(r=>r.status==='provisional').length;return `${intro('El campamento, en vivo','Registra un único ganador por juego y sigue las victorias.','<button class="btn small" data-refresh>↻ Actualizar</button>')}<section class="hero"><div><div class="eyebrow">Cada patrulla cuenta</div><h2>La próxima victoria<br>empieza aquí.</h2><p>Al terminar un juego, elige su patrulla ganadora. Una victoria suma un punto a su patrulla y tropa.</p></div><button class="btn gold" data-tab="games">+ Registrar ganador</button></section><div class="stats"><div class="stat"><span>Patrullas en juego</span><strong>${state.patrols.length}</strong></div><div class="stat"><span>Tropas temporales</span><strong>4</strong></div><div class="stat"><span>Resultados validados</span><strong>${valid}</strong></div><div class="stat"><span>Por validar</span><strong>${pending}</strong></div></div><div class="grid"><section class="card"><div class="section-head"><h2>Patrullas en la cima</h2><button class="btn small" data-tab="rank">Ver todas →</button></div><p class="help">Solo las victorias validadas cuentan en la tabla.</p>${s.rows.length?s.rows.slice(0,5).map(patrolRow).join(''):'<div class="empty">Agrega las patrullas reales desde Control para comenzar.</div>'}</section><div><section class="card"><div class="section-head"><h2>La batalla por El Dorado</h2><span class="badge gold">Domingo</span></div>${allianceBars(s)}<p class="help">Módulos 5 y 6. El domingo comienza en cero.</p></section><section class="card"><div class="section-head"><h2>Últimos ganadores</h2><span class="badge">${state.results.length}</span></div>${state.results.length?state.results.slice().sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,3).map(r=>`<div class="list-row"><span class="patrol-icon">★</span><div class="grow"><strong>${esc(gname(r.game))}</strong><small>${r.winner?esc(pname(r.winner)):'Sin ganador'}</small></div><span class="badge ${r.status==='provisional'?'gold':''}">${statusName(r.status)}</span></div>`).join(''):'<div class="empty">Todavía no hay ganadores.<br>Elige un juego para registrar el primero.</div>'}</section></div></div>`;}
function scoreValue(type,id,value,label){return admin()?`<button class="value score-adjust" data-adjust-target="${type}" data-adjust-id="${id}" title="Mantén presionado o usa clic derecho para ajustar"><strong>${value}</strong><small>${label}</small></button>`:`<div class="value"><strong>${value}</strong><small>${label}</small></div>`;}
function allianceBars(s,editable=false){const max=Math.max(...s.alliances.map(a=>a.points),1);return s.alliances.map(a=>`<div class="tally"><div><div class="scoreline"><strong>${a.name}</strong>${editable?scoreValue('alliance',a.id,`${a.points} pts`,'ajuste manual'):`<strong>${a.points} pts</strong>`}</div><div class="bar ${a.id==='muiscas'?'gold':''}"><span style="width:${Math.max(0,a.points)/max*100}%"></span></div></div></div>`).join('');}
function games(){const dayBlocks=['Todos',...BLOCKS.filter(b=>state.games.some(g=>g.phase===day&&g.block===b))],gs=state.games.filter(g=>g.enabled&&g.phase===day&&(block==='Todos'||g.block===block)&&g.name.toLowerCase().includes(search.toLowerCase()));return `${intro('Juegos y actividades','Elige el día, luego el juego. Solo registra qué patrulla ganó.')}<div class="tabs" aria-label="Día del programa">${Object.entries(PHASES).map(([id,name])=>`<button class="chip ${day===id?'active':''}" data-day="${id}">${name}</button>`).join('')}</div><label class="field"><span class="sr-only">Buscar juego</span><input id="game-search" type="search" value="${esc(search)}" placeholder="Buscar juego de ${PHASES[day]}…"></label><div class="tabs" aria-label="Filtrar por módulo">${dayBlocks.map(b=>`<button class="chip ${block===b?'active':''}" data-block="${b}">${b}</button>`).join('')}</div><div class="game-list">${gs.map(g=>{const result=state.results.find(r=>r.game===g.id&&r.status!=='void'),cheer=g.id.startsWith('barras');return `<article class="card game ${cheer?'cheer-game':''}"><div class="meta"><span class="badge ${g.phase==='domingo'?'gold':''}">${g.block}</span>${cheer?'<span class="badge cheer-badge">Extra · barras</span>':''}<small>${PHASES[g.phase]} · ${g.time}</small></div><div><h3>${esc(g.name)}</h3><p>${esc(g.rules)}</p></div><small>${g.scope==='all'?'Todas las tropas':g.scope==='europeos'?'Expediciones europeas':'Confederaciones Muiscas'} · ${result?`Ganó: ${esc(pname(result.winner))}`:'Sin ganador registrado'}</small><footer><button class="btn primary" data-result="${g.id}" ${state.closed||!!result?'disabled':''}>${result?'Ganador registrado':'Registrar ganador'}</button></footer></article>`;}).join('')||'<div class="empty">No se encontraron juegos para este día.</div>'}</div>`;}
const kitchenScores=meal=>(state.kitchen_scores||[]).filter(x=>(x.meal||'almuerzo')===meal);
function kitchen(){const scores=kitchenScores(kitchenMeal),total=x=>Object.values(x.values).reduce((n,v)=>n+Number(v),0),ranked=[...scores].sort((a,b)=>total(b)-total(a)),best=ranked[0]?total(ranked[0]):0,leaders=ranked.filter(x=>total(x)===best),final=state.results.find(r=>r.game===`cocina-${kitchenMeal}`&&r.status!=='void');return `${intro('Cocina · sábado','Califica por comida. Cada comida tendrá un ganador que suma un punto al evento.')}<section class="card"><div class="section-head"><h2>Calificar por tropa</h2><span class="badge gold">${KITCHEN_MEALS[kitchenMeal]}</span></div><label class="field"><span>Comida a calificar</span><select id="kitchen-meal">${options(Object.entries(KITCHEN_MEALS),kitchenMeal)}</select></label><div class="actions">${TROOPS.map(t=>`<button class="btn" data-kitchen-troop="${t.id}">${esc(t.short)}</button>`).join('')}</div><p class="help">Una patrulla ya calificada para esta comida pide confirmación antes de modificarla.</p></section><section class="card"><div class="section-head"><h2>Ranking previo · ${KITCHEN_MEALS[kitchenMeal]}</h2><span class="badge">${scores.length}/${state.patrols.length} calificadas</span></div>${ranked.map((x,i)=>`<div class="list-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><div class="grow"><strong>${esc(pname(x.patrol))}</strong><small>${total(x).toFixed(1)} / 25 estrellas</small></div>${leaders.includes(x)?'<span class="badge gold">Primer lugar</span>':''}</div>`).join('')||'<p class="empty">Aún no hay calificaciones para esta comida.</p>'}${admin()&&!final&&scores.length===state.patrols.length?`<button class="btn primary full" data-kitchen-final>${leaders.length>1?'Resolver empate y declarar ganador':'Declarar ganador de '+KITCHEN_MEALS[kitchenMeal].toLowerCase()}</button>`:''}${final?`<p class="notice">Ganador de ${KITCHEN_MEALS[kitchenMeal].toLowerCase()} enviado a validación: ${esc(pname(final.winner))}.</p>`:''}</section>`;}
function kitchenTroop(id){const t=troop(id),by=Object.fromEntries(kitchenScores(kitchenMeal).map(x=>[x.patrol,x]));open(`${head('Cocina · '+esc(t.short)+' · '+KITCHEN_MEALS[kitchenMeal])}${state.patrols.filter(p=>p.troop===id).map(p=>`<div class="list-row"><div class="grow"><strong>${esc(p.name)}</strong><small>${by[p.id]?'Ya calificada':'Pendiente'}</small></div>${by[p.id]?`<button class="btn small recalibrate" data-kitchen-patrol="${p.id}">Recalificar</button>`:`<button class="btn small primary" data-kitchen-patrol="${p.id}">Calificar</button>`}</div>`).join('')}`);}
function kitchenReconfirm(id){const p=state.patrols.find(x=>x.id===id);open(head('Confirmar recalificación')+'<p class="rule">'+esc(p.name)+' ya tiene una calificación guardada. ¿Deseas modificarla?</p><div class="actions"><button class="btn" data-close>Cancelar</button><button class="btn recalibrate" id="confirm-recalibrate">Recalificar</button></div>');$('#confirm-recalibrate').onclick=()=>kitchenScoreForm(id);}
function kitchenScoreForm(id){const p=state.patrols.find(x=>x.id===id),existing=kitchenScores(kitchenMeal).find(x=>x.patrol===id),keys=[['presentation','Presentación'],['complexity','Complejidad'],['flavor','Sabor'],['teamwork','Trabajo en equipo'],['cleanliness','Limpieza del área']],v={...(existing?.values||Object.fromEntries(keys.map(([k])=>[k,0]))) };const draw=()=>{const stars=k=>[1,2,3,4,5].map(i=>{const n=Number(v[k]||0),c=n>=i?'full':n===i-.5?'half':'empty';return `<button type="button" class="star ${c}" data-kitchen-star="${k}:${i}">★</button>`;}).join('');open(`${head('Calificar · '+esc(p.name)+' · '+KITCHEN_MEALS[kitchenMeal])}<form id="kitchen-score-form">${keys.map(([k,l])=>`<div class="star-row"><strong>${l}</strong><div>${stars(k)}</div><small>${Number(v[k]||0).toFixed(1)} / 5</small></div>`).join('')}<button class="btn primary full">Guardar calificación</button></form>`);document.querySelectorAll('[data-kitchen-star]').forEach(b=>b.onclick=()=>{const [k,n]=b.dataset.kitchenStar.split(':'),i=Number(n),x=Number(v[k]||0);v[k]=x===i?i-.5:x===i-.5?i-1:i;draw();});$('#kitchen-score-form').onsubmit=e=>{e.preventDefault();if(Object.values(v).some(x=>x<1))return toast('Cada criterio debe tener al menos una estrella.');run(()=>save('kitchen_score',{patrol:id,meal:kitchenMeal,values:v}));};};draw();}

function kitchenFinal(){const scores=kitchenScores(kitchenMeal),total=x=>Object.values(x.values).reduce((n,v)=>n+Number(v),0),best=Math.max(...scores.map(total)),leaders=scores.filter(x=>total(x)===best);open(`${head('Declarar ganador · '+KITCHEN_MEALS[kitchenMeal])}<p class="help">${leaders.length===1?`Primer lugar: <strong>${esc(pname(leaders[0].patrol))}</strong>.`: 'Hay empate en el primer lugar. Resuélvanlo en vivo antes de continuar.'}</p><form id="kitchen-final-form"><label class="field"><span>Patrulla ganadora</span><select name="winner">${options(leaders.map(x=>[x.patrol,`${pname(x.patrol)} · ${total(x).toFixed(1)} estrellas`]),leaders[0]?.patrol||'')}</select></label>${leaders.length>1?'<label class="field"><span>Cómo se resolvió el desempate</span><textarea name="reason" required minlength="5" maxlength="500"></textarea></label>':''}<p class="help">El resultado quedará Por validar en Resultados y, al validarlo, sumará 1 punto a la patrulla y su tropa.</p><button class="btn primary full">Enviar ganador a validación</button></form>`);$('#kitchen-final-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('kitchen_finalize',{meal:kitchenMeal,winner:f.get('winner'),reason:f.get('reason')||''}));};}
function rank(){const s=summary(state),patrols=s.rows.map((p,i)=>`<div class="list-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="patrol-icon">${troop(p.troop)?.icon||'⚑'}</span><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(troop(p.troop)?.short)}</small></div>${scoreValue('patrol',p.id,`${p.wins}`,`victorias · ${p.points} pts`)}</div>`).join('');return `${intro('Tabla de posiciones','Cada juego validado entrega una victoria y un punto.','<button class="btn small" data-export="csv">↓ CSV</button>')}<div class="grid"><section class="card"><div class="section-head"><h2>Mejor patrulla</h2><span class="badge">Todo el evento</span></div>${s.patrolTie?'<div class="notice">Empate en el primer puesto. Se requiere el desempate del reglamento.</div>':''}${patrols||'<div class="empty">No hay patrullas registradas.</div>'}<p class="help">${admin()?'Mantén presionado un puntaje (o usa clic derecho) para crear un ajuste registrado.':'Cada juego tiene un solo ganador. Una victoria equivale a un punto.'}</p></section><div><section class="card"><h2>Competencia del sábado</h2>${s.troops.map(t=>`<div class="list-row"><span class="patrol-icon">${t.icon}</span><div class="grow"><strong>${esc(t.short)}</strong><small>${t.alliance==='europeos'?'Europeos':'Muiscas'} ${s.leaders[t.alliance]?.id===t.id?'· Líder':''}</small></div>${scoreValue('troop',t.id,t.points,'victorias')}</div>`).join('')}<p class="help">Incluye viernes y sábado. Un empate deja el liderazgo pendiente.</p></section><section class="card"><h2>Captura o defensa de El Dorado</h2>${allianceBars(s,true)}<p class="help">${s.winning?`${s.winning.name} llevan la ventaja.`:'Sin ventaja: la batalla está empatada.'}</p><h3>Premio de tropa</h3><p class="rule">${s.bestTroop?esc(s.bestTroop.name):'Pendiente de resolver la alianza ganadora y el liderazgo del sábado.'}</p><span class="badge ${state.closed?'':'gold'}">${state.closed?'Clasificación cerrada':'Clasificación provisional'}</span></section></div></div>`;}
function adjustPointsForm(type,id){if(!admin())return;const names={patrol:pname(id),troop:troop(id)?.short||id,alliance:id==='europeos'?'Europeos':'Muiscas'},label={patrol:'patrulla',troop:'tropa',alliance:'alianza'}[type];open(`${head('Ajustar puntaje')}<p class="rule">${esc(names[type])} · ajuste directo de ${label}. El ajuste se registrará en Resultados y podrá reabrirse o anularse.</p><form id="adjust-points-form"><label class="field"><span>Puntos a sumar o restar</span><input name="amount" type="number" required min="-1000" max="1000" step="1" inputmode="numeric" placeholder="Ej. 1 o -1"></label><label class="field"><span>Motivo</span><textarea name="reason" required minlength="5" maxlength="500" placeholder="Ej. Desempate realizado en campo"></textarea></label><button class="btn primary full">Registrar ajuste</button></form>`);$('#adjust-points-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount'));if(!Number.isInteger(amount)||amount===0)return toast('Indica un número entero distinto de cero.');run(()=>save('adjust_points',{target_type:type,target:id,amount,reason:f.get('reason')}));};}
function statusName(s){return {validated:'Validado',provisional:'Por validar',void:'Anulado'}[s]||s;}
function results(){const pending=state.results.filter(r=>r.status==='provisional').length;return `${intro('Resultados y ajustes','Revisa y valida cada ganador o ajuste del campamento.')}<div class="results-toolbar"><div class="tabs">${['Todos','Pendientes','Validados','Anulados'].map(b=>`<button class="chip ${(results.filter||'Todos')===b?'active':''}" data-result-filter="${b}">${b}</button>`).join('')}</div><button class="btn small primary" data-validate-all ${state.closed||!pending?'disabled':''}>✓ Validar todo${pending?' · '+pending:''}</button></div>${state.results.filter(r=>!results.filter||results.filter==='Todos'||r.status===({Pendientes:'provisional',Validados:'validated',Anulados:'void'}[results.filter])).slice().sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).map(r=>{const adjustment=r.kind==='adjustment',amount=Number(r.adjustment_amount||0),details=adjustment?`<div class="scoreline"><span>${esc(adjustmentTarget(r))}</span><strong>${amount>0?'+':''}${amount} <small>puntos manuales</small></strong></div>`:`<div class="scoreline"><span>★ ${esc(pname(r.winner))}</span><strong>Ganador <small>→ 1 punto</small></strong></div>`;return `<article class="card"><div class="section-head"><div><h2>${esc(resultName(r))}</h2><small>${adjustment?'Ajuste manual':PHASES[r.phase]}</small></div><span class="badge ${r.status==='provisional'?'gold':r.status==='void'?'red':''}">${statusName(r.status)}</span></div>${details}<p class="help">Registrado por ${esc(r.created_by)} · ${date(r.updated_at)}${r.notes?'<br>Motivo: '+esc(r.notes):r.reason?'<br>Motivo: '+esc(r.reason):''}</p><div class="result-controls">${admin()?[(r.status==='validated'||r.status==='void')&&r.kind!=='tournament'?`<button class="btn small" data-reopen-result="${r.id}" ${state.closed?'disabled':''}>Reabrir</button>`:'',r.status!=='void'&&!adjustment?`<button class="btn small" data-edit-result="${r.id}" ${state.closed?'disabled':''}>Corregir</button>`:'',r.status==='provisional'?`<button class="btn small primary" data-status="validated" data-id="${r.id}" ${state.closed?'disabled':''}>Validar</button>`:'',r.status!=='void'?`<button class="btn small danger" data-status="void" data-id="${r.id}" ${state.closed?'disabled':''}>Anular</button>`:''].join(''):''}</div></article>`;}).join('')||'<div class="card empty">Todavía no hay registros.</div>'}`;}
function control(){if(!admin())return '';return `${intro('Control del campamento','Administración de juegos, patrullas y registro de operaciones.')}<div class="card"><div class="section-head"><h2>Operación del evento</h2><span class="badge gold">Super dios</span></div><div class="actions" style="justify-content:flex-start"><button class="btn primary" data-add-patrol>+ Agregar patrulla</button><button class="btn" data-rules>Gestionar juegos</button><button class="btn" data-export="json">↓ Respaldo completo</button><button class="btn danger" data-clear-results>Borrar puntajes</button><button class="btn ${state.closed?'primary':'danger'}" data-close-event>${state.closed?'Reabrir evento':'Cerrar clasificación'}</button></div><p class="help">${isDemo()?'Los cambios de esta demostración no afectan el evento real.':'Las claves se configuran en Supabase. No se muestran ni se descargan.'}</p></div><div class="grid"><section class="card"><div class="section-head"><h2>Patrullas</h2><span class="badge">${state.patrols.length}</span></div>${state.patrols.map(p=>`<div class="list-row"><span class="patrol-icon">${troop(p.troop)?.icon}</span><div class="grow"><strong>${esc(p.name)}</strong><small>${esc(troop(p.troop)?.short)} · ${p.members} integrantes<br>${esc(p.group)}</small></div><button class="btn small" data-edit-patrol="${p.id}">Editar</button></div>`).join('')||'<p class="empty">Agrega las patrullas inscritas.</p>'}</section><section class="card"><div class="section-head"><h2>Bitácora</h2><span class="badge">${state.logs?.length||0} eventos</span></div><p class="help">Ingresos, salidas y cambios realizados desde la aplicación. Nombre declarado por cada dirigente; no verifica identidad.</p>${(state.logs||[]).slice(0,100).map(l=>`<details class="log"><summary><strong>${esc(l.actor)}</strong> · ${esc(l.action)}<br><small>${date(l.at)} · ${l.role==='admin'?'Super dios':'Dios'}</small></summary><pre>${esc(JSON.stringify({datos:l.payload,antes:l.before,despues:l.after},null,2))}</pre></details>`).join('')||'<p class="empty">Todavía no hay operaciones.</p>'}${(state.logs?.length||0)>100?'<p class="help">Vista de las 100 operaciones más recientes. El respaldo incluye todas las cargadas.</p>':''}</section></div>`;}
function patrolForm(id){const p=state.patrols.find(x=>x.id===id)||{id:uid(),name:'',group:'',troop:'quezada',members:6};open(`${head(id?'Editar patrulla':'Nueva patrulla')}<form id="patrol-form"><label class="field"><span>Nombre de patrulla</span><input name="name" required maxlength="60" value="${esc(p.name)}"></label><label class="field"><span>Grupo de origen</span><input name="group" required maxlength="100" value="${esc(p.group)}"></label><div class="form-grid"><label class="field"><span>Tropa temporal</span><select name="troop">${options(TROOPS.map(t=>[t.id,t.short]),p.troop)}</select></label><label class="field"><span>Integrantes</span><input name="members" type="number" min="1" max="30" required value="${p.members}"></label></div><p class="help">La tropa no se puede cambiar cuando la patrulla ya tiene resultados o participa en un torneo.</p><button class="btn primary full">Guardar patrulla</button></form>`);$('#patrol-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('upsert_patrol',{id:p.id,name:f.get('name').trim(),group:f.get('group').trim(),troop:f.get('troop'),members:Number(f.get('members'))}));};}
function clearResultsForm(){
  const results=state.results.length,tournaments=state.tournaments.length;
  open(`${head('Borrar puntajes')}<p class="rule">Se borrarán ${results} ${results===1?'resultado':'resultados'} y ${tournaments} ${tournaments===1?'torneo':'torneos'}. Se conservan patrullas, grupos, juegos y la bitácora. El evento quedará abierto.</p><form id="clear-results-form"><label class="field"><span>Motivo</span><input name="reason" required minlength="5" maxlength="500" placeholder="Ej. Reinicio para pruebas"></label><label class="field"><span>Escribe DELETE para confirmar</span><input name="confirm" required pattern="DELETE" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="DELETE"></label><button class="btn danger full">Borrar todos los puntajes</button></form>`);
  $('#clear-results-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('clear_results',{confirm:f.get('confirm'),reason:f.get('reason')}));};
}
function reopenResultForm(id){
  const r=state.results.find(x=>x.id===id);if(!r)return;
  open(`${head('Reabrir resultado')}<p class="rule">${esc(gname(r.game))} · ${esc(r.label)} · ${esc(pname(r.winner))}<br>El resultado pasará a <strong>Por validar</strong>. Después podrás corregir el ganador y validarlo de nuevo. La operación queda en la bitácora.</p><form id="reopen-form"><label class="field"><span>Motivo</span><input name="reason" required minlength="5" maxlength="500" placeholder="Ej. Corrección solicitada por organización"></label><button class="btn primary full">Reabrir resultado</button></form>`);
  $('#reopen-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('reopen_result',{id:r.id,version:r.version,reason:f.get('reason')}));};
}
function validateAllForm(){
  const pending=state.results.filter(r=>r.status==='provisional');
  if(!pending.length)return toast('No hay resultados pendientes por validar.');
  if(state.closed)return toast('El evento está cerrado. Reábrelo para validar resultados.');
  const selected=new Set();
  const blocks=[...new Set(state.games.map(g=>g.block).filter(Boolean))].sort((a,b)=>BLOCKS.indexOf(a)-BLOCKS.indexOf(b));
  const groups=[...new Set(state.patrols.map(p=>p.group).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'));
  const gameOf=r=>state.games.find(g=>g.id===r.game)||{};
  const kindOf=r=>r.kind==='tournament'?'Torneo':String(r.game||'').startsWith('bandas')?'Bandas':'Directo';
  const patrolsOf=r=>(r.entries||[]).map(e=>state.patrols.find(p=>p.id===e.patrol)).filter(Boolean);
  const pointsOf=r=>(r.entries||[]).reduce((n,e)=>n+Number(e.points||0),0);
  const filters=[['all','Todos'],['block','Módulo'],['phase','Día'],['kind','Tipo'],['scope','Alcance de tropa'],['patrol','Patrulla afectada'],['group','Grupo afectado'],['custom','Personalizado']];
  open(`${head('Validar resultados')}<p class="help">Revisa los resultados pendientes y marca los que quieras validar. Al cambiar de filtro se limpia la selección, así validas solo lo que tienes a la vista. Se validan todos juntos y cada uno guarda el nombre de quien valida como comentario.</p><form id="bulk-validate-form"><div class="form-grid bulk-filters"><label class="field"><span>Filtrar por</span><select id="bulk-filter">${options(filters,'all')}</select></label><div id="bulk-filter-extra"></div></div><div class="bulk-list-head"><label class="bulk-selectall"><input type="checkbox" id="bulk-all"> Seleccionar visibles</label><div class="actions"><span id="bulk-count" class="bulk-summary"></span><button type="button" class="btn small" id="bulk-clear">Limpiar</button></div></div><div id="bulk-list" class="bulk-list"></div><div id="bulk-total" class="bulk-summary" style="margin:10px 0 16px"></div><label class="field"><span>Nombre de quien valida</span><input name="actor" required minlength="2" maxlength="60" value="${esc(getSession()?.name||'')}" placeholder="Ej. Bryan Ruz"></label><p class="help">Se guardará como «Validado por …» en cada resultado seleccionado.</p><button class="btn primary full" id="bulk-submit">Validar seleccionados</button></form>`);
  modal.classList.add('bulk');
  const filter=$('#bulk-filter'),extra=$('#bulk-filter-extra'),list=$('#bulk-list'),all=$('#bulk-all');
  let mode='all',value='';
  const matches=r=>{
    const g=gameOf(r),ps=patrolsOf(r);
    if(mode==='block')return g.block===value;
    if(mode==='phase')return r.phase===value;
    if(mode==='kind')return kindOf(r)===value;
    if(mode==='scope')return (g.scope||'all')===value;
    if(mode==='patrol')return ps.some(p=>p.id===value);
    if(mode==='group')return ps.some(p=>p.group===value);
    if(mode==='custom'){const q=value.trim().toLowerCase();return !q||[gname(r.game),r.label,kindOf(r),...ps.map(p=>p.name),...ps.map(p=>p.group)].join(' ').toLowerCase().includes(q);}
    return true;
  };
  const visible=()=>pending.filter(matches);
  const drawSummary=()=>{
    const boxes=[...list.querySelectorAll('input[data-bulk-id]')],checked=boxes.filter(b=>b.checked);
    all.checked=boxes.length>0&&checked.length===boxes.length;all.indeterminate=checked.length>0&&checked.length<boxes.length;all.disabled=!boxes.length;
    const chosen=pending.filter(r=>selected.has(r.id)),points=chosen.reduce((n,r)=>n+pointsOf(r),0);
    $('#bulk-count').textContent=`${checked.length} visibles`;
    $('#bulk-total').textContent=`${chosen.length} ${chosen.length===1?'seleccionado':'seleccionados'} · ${points} ${points===1?'punto':'puntos'} por asignar`;
    $('#bulk-submit').disabled=!chosen.length;
  };
  const drawList=()=>{
    const xs=visible().slice().sort((a,b)=>b.updated_at.localeCompare(a.updated_at));
    list.innerHTML=xs.map(r=>{const g=gameOf(r),ps=patrolsOf(r),points=pointsOf(r);return `<label class="bulk-item"><input type="checkbox" data-bulk-id="${r.id}" ${selected.has(r.id)?'checked':''}><div class="grow"><div class="bulk-title"><strong>${esc(gname(r.game))}</strong><span class="badge">${esc(g.block||'Sin módulo')} · ${esc(PHASES[r.phase]||'')}</span></div><small>${kindOf(r)} · Ganador: ★ ${esc(pname(r.winner))} · ${points} ${points===1?'punto':'puntos'} en total</small><div class="bulk-points">${(r.entries||[]).map(e=>{const p=state.patrols.find(p=>p.id===e.patrol);return `<span>${esc(p?.name||pname(e.patrol))}${p?.group?' · '+esc(p.group):''} <b>+${Number(e.points||0)}</b></span>`;}).join('')}</div></div></label>`;}).join('')||'<div class="empty">No hay resultados pendientes con este filtro.</div>';
    list.querySelectorAll('input[data-bulk-id]').forEach(box=>box.onchange=()=>{box.checked?selected.add(box.dataset.bulkId):selected.delete(box.dataset.bulkId);drawSummary();});
    drawSummary();
  };
  const drawExtra=()=>{
    let html='',opts=[];
    if(mode==='block')opts=blocks.map(b=>[b,b]);
    else if(mode==='phase')opts=Object.entries(PHASES);
    else if(mode==='kind')opts=[['Directo','Directo'],['Torneo','Torneo'],['Bandas','Bandas']];
    else if(mode==='scope')opts=[['all','Todas las tropas'],['europeos','Europeos'],['muiscas','Muiscas']];
    else if(mode==='patrol')opts=state.patrols.map(p=>[p.id,`${p.name}${p.group?' · '+p.group:''}`]);
    else if(mode==='group')opts=groups.map(g=>[g,g]);
    if(mode!=='custom'&&opts.length&&!opts.some(([id])=>id===value))value=opts[0][0];
    if(mode==='custom')html=`<label class="field"><span>Buscar</span><input id="bulk-value" type="search" value="${esc(value)}" placeholder="Juego, patrulla o grupo…"></label>`;
    else if(opts.length)html=`<label class="field"><span>${mode==='patrol'?'Patrulla':mode==='group'?'Grupo':mode==='scope'?'Tropas':'Valor'}</span><select id="bulk-value">${options(opts,value)}</select></label>`;
    extra.innerHTML=html;
    const input=$('#bulk-value');
    if(input){const update=()=>{if(input.value!==value)selected.clear();value=input.value;drawList();};input.onchange=update;input.oninput=update;}
  };
  filter.onchange=()=>{mode=filter.value;value='';selected.clear();drawExtra();drawList();};
  all.onchange=()=>{visible().forEach(r=>all.checked?selected.add(r.id):selected.delete(r.id));drawList();};
  $('#bulk-clear').onclick=()=>{selected.clear();drawList();};
  $('#bulk-validate-form').onsubmit=e=>{
    e.preventDefault();
    const actor=new FormData(e.target).get('actor').trim();
    const items=[...selected].map(id=>{const r=state.results.find(r=>r.id===id);return r?{id:r.id,version:r.version}:null;}).filter(Boolean);
    if(!items.length)return toast('Selecciona al menos un resultado.');
    run(async()=>{await save('validate_results',{items,actor});toast(`${items.length} ${items.length===1?'resultado validado':'resultados validados'} por ${actor}.`);});
  };
  drawExtra();drawList();
}
function resultForm(gameId,resultId){
  const g=state.games.find(x=>x.id===gameId),r=state.results.find(x=>x.id===resultId),ps=state.patrols.filter(p=>eligible(p,g));
  if(!ps.length)return toast('Agrega patrullas elegibles desde Control.');
  const troopLabels={quezada:'Quezada',federmann:'Federmann',zaque:'Quemuen',zipa:'Tisques'};
  open(`${head(r?'Corregir ganador':esc(g.name))}<form id="winner-form"><label class="field"><span class="sr-only">Buscar patrulla o grupo</span><input id="winner-search" type="search" placeholder="Buscar patrulla o grupo…" autocomplete="off"></label><div class="tabs" id="winner-troops" aria-label="Filtrar por tropa">${[['all','Todas'],...TROOPS.map(t=>[t.id,troopLabels[t.id]||t.short])].map(([id,name])=>`<button type="button" class="chip ${id==='all'?'active':''}" data-winner-troop="${id}">${name}</button>`).join('')}</div><label class="field"><span>Patrulla ganadora</span><select name="winner" id="winner-select" required></select></label>${r?'<label class="field"><span>Motivo de la corrección</span><input name="reason" required minlength="5" maxlength="500"></label>':''}<button class="btn primary full">${r?'Guardar corrección':'Registrar ganador'}</button></form>`);
  const sel=$('#winner-select'),searchInput=$('#winner-search'),chips=$('#winner-troops');
  let filter='all',selection=r?.winner||'';
  const fill=()=>{const q=searchInput.value.trim().toLowerCase(),visible=ps.filter(p=>(filter==='all'||p.troop===filter)&&(!q||p.name.toLowerCase().includes(q)||String(p.group||'').toLowerCase().includes(q))),keep=visible.some(p=>p.id===selection)?selection:'';sel.innerHTML=options([['',visible.length?'Seleccionar ganador…':'Sin patrullas en este filtro'],...visible.map(p=>[p.id,`${p.name||''} · ${p.group||''}`])],keep);selection=keep;};
  sel.onchange=()=>{selection=sel.value;};
  searchInput.oninput=fill;
  chips.onclick=e=>{const b=e.target.closest('[data-winner-troop]');if(!b)return;filter=b.dataset.winnerTroop;chips.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active',c.dataset.winnerTroop===filter));fill();};
  fill();
  $('#winner-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('save_winner',{id:r?.id||uid(),game:g.id,winner:f.get('winner'),reason:f.get('reason')||'',version:r?.version||0}));};
}
function entryHtml(e,ps){return `<div class="entry form-grid"><label class="field"><span>Patrulla</span><select required>${options([['','Seleccionar…'],...ps.map(p=>[p.id,p.name])],e.patrol)}</select></label><label class="field"><span>Marcador <button type="button" data-remove-entry style="float:right;border:0;background:none;color:var(--muted)" aria-label="Quitar patrulla">×</button></span><input class="score-input" type="number" min="0" max="1000000" step="0.01" required value="${e.score}" inputmode="decimal"></label></div>`;}
function tournamentView(gameId){const g=state.games.find(x=>x.id===gameId),t=state.tournaments.find(t=>t.game===gameId&&!t.cancelled);if(!t){const ps=state.patrols.filter(p=>eligible(p,g));open(`${head('Crear torneo')}<h3>${esc(g.name)}</h3><p class="help">Eliminación directa. Un pase libre no suma victorias. El campeón obtiene 3 puntos y una victoria; el subcampeón 2 puntos y los demás 1. El torneo completo debe validarse al terminar. No mezclar con resultados directos del mismo juego y patrulla.</p><form id="tournament-form"><label class="field"><span>Nombre del torneo</span><input name="name" required maxlength="80" value="Torneo ${esc(g.name)}"></label><p class="help">Selecciona de 2 a 32 patrullas. Los cruces se sortean al crear.</p>${ps.map(p=>`<label class="list-row"><input type="checkbox" name="participants" value="${esc(p.id)}"><span>${esc(p.name)} <small>· ${esc(troop(p.troop)?.short)}</small></span></label>`).join('')}<button class="btn primary full" style="margin-top:20px" ${state.closed?'disabled':''}>Sortear y crear torneo</button></form>`);$('#tournament-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let ids=f.getAll('participants');if(ids.length<2||ids.length>32)return toast('Selecciona entre 2 y 32 patrullas.');for(let i=ids.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[ids[i],ids[j]]=[ids[j],ids[i]];}run(async()=>{await save('create_tournament',{id:uid(),game:g.id,name:f.get('name'),participants:ids});tournamentView(gameId);});};return;}
  open(`${head(esc(t.name))}<p class="help">${esc(g.name)} · ${t.participants.length} patrullas. ${g.metric==='lower'?'Menor marcador gana.':'Mayor marcador gana.'} Los empates requieren desempate antes de avanzar.</p>${t.rounds.map((round,ri)=>`<section class="bracket-round"><h3>${ri===t.rounds.length-1?'Final':'Ronda '+(ri+1)}</h3>${round.map((m,mi)=>`<div class="list-row"><div class="grow"><strong>${m.a?esc(pname(m.a)):'Por definir'} ${m.scoreA!==null?'· '+m.scoreA:''}</strong><small>vs. ${m.b?esc(pname(m.b)):'Por definir'} ${m.scoreB!==null?'· '+m.scoreB:''}</small>${m.winner?'<small>★ '+esc(pname(m.winner))+(m.bye?' · pase libre':'')+'</small>':''}</div>${m.a&&m.b&&!m.winner?`<button class="btn small primary" data-match="${t.id}" data-round="${ri}" data-index="${mi}" ${state.closed?'disabled':''}>Anotar</button>`:''}</div>`).join('')}</section>`).join('')}<p class="help">Los resultados de encuentros quedan en la bitácora. La final crea el resultado oficial pendiente de validación.</p>${admin()?`<button class="btn danger full" data-cancel-tournament="${t.id}" ${state.closed?'disabled':''}>Anular torneo para corregir</button>`:''}`);
}
function matchForm(id,ri,mi){const t=state.tournaments.find(t=>t.id===id),m=t.rounds[ri][mi],g=state.games.find(g=>g.id===t.game);open(`${head('Resultado del encuentro')}<p class="help">${esc(g.name)} · ${g.metric==='lower'?'Menor valor gana':'Mayor valor gana'}. Incluye el desempate en el marcador; explícalo si corresponde.</p><form id="match-form"><div class="form-grid"><label class="field"><span>${esc(pname(m.a))}</span><input name="a" required type="number" min="0" max="1000000" step="0.01" class="score-input" inputmode="decimal"></label><label class="field"><span>${esc(pname(m.b))}</span><input name="b" required type="number" min="0" max="1000000" step="0.01" class="score-input" inputmode="decimal"></label></div><label class="field"><span>Observación</span><textarea name="notes" maxlength="1000"></textarea></label><p class="help">Al guardar se avanza al ganador. Verifica el marcador: si hubo un error, el administrador puede anular el torneo y crear uno nuevo para conservar el historial sin alterar cruces ya jugados.</p><button class="btn primary full">Confirmar y avanzar ganador</button></form>`);$('#match-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=Number(f.get('a')),b=Number(f.get('b'));if(a===b)return toast('Resuelve el empate antes de avanzar.');run(async()=>{await save('score_match',{id,round:ri,index:mi,a,b,version:t.version,notes:f.get('notes')});tournamentView(g.id);});};}
function rules(){let active=state.games[0]?.id||'';const draw=()=>{const g=state.games.find(x=>x.id===active)||{id:uid(),name:'Nuevo juego',phase:'sabado',block:'Masivos',time:'',scope:'all',rules:'',enabled:true};open(`${head('Gestionar juegos')}<p class="help">Cada juego habilitado permite registrar un único ganador y entrega un punto. Deshabilitarlo lo oculta a dirigentes y lo excluye de las posiciones; no se elimina su historial.</p><div class="actions"><button class="btn small primary" id="new-game">+ Agregar juego</button></div><label class="field"><span>Juego existente</span><select id="rule-game">${options([['','Seleccionar…'],...state.games.map(x=>[x.id,`${x.enabled?'':'[Deshabilitado] '}${x.name} · ${PHASES[x.phase]} · ${x.block}`])],state.games.some(x=>x.id===active)?active:'')}</select></label><form id="rule-form"><label class="field"><span>Nombre del juego</span><input name="name" required minlength="2" maxlength="100" value="${esc(g.name)}"></label><div class="form-grid"><label class="field"><span>Día</span><select name="phase">${options(Object.entries(PHASES),g.phase)}</select></label><label class="field"><span>Hora en el programa</span><input name="time" maxlength="40" value="${esc(g.time)}" placeholder="Ej. 16:30"></label></div><label class="field"><span>Parte del programa</span><select name="block">${options(BLOCKS.map(x=>[x,x]),g.block)}</select></label><label class="field"><span>Quiénes participan</span><select name="scope">${options([['all','Todas las tropas'],['europeos','Solo Europeos'],['muiscas','Solo Muiscas']],g.scope)}</select></label><label class="field"><span>Instrucción breve para el dirigente</span><textarea name="rules" maxlength="2000">${esc(g.rules)}</textarea></label><label class="list-row"><input name="enabled" type="checkbox" ${g.enabled?'checked':''}> Juego habilitado</label><p class="help">No hay métricas ni escalas: el dirigente solo elige al ganador. No se eliminan juegos; para retirarlos del evento, deshabilítalos.</p><button class="btn primary full">Guardar juego</button></form>`);$('#new-game').onclick=()=>{active='';draw();};$('#rule-game').onchange=e=>{active=e.target.value;draw();};$('#rule-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('save_game',{id:g.id,name:f.get('name').trim(),phase:f.get('phase'),block:f.get('block'),time:f.get('time').trim(),scope:f.get('scope'),rules:f.get('rules').trim(),enabled:f.has('enabled')}));};};draw();}
function exportFile(kind){const s=summary(state);let content,mime;if(kind==='json'){content=JSON.stringify({...state,exported_at:new Date().toISOString()},null,2);mime='application/json';}else{const cell=x=>'"'+String(x??'').replaceAll('"','""')+'"';content='\ufeff'+[['Patrulla','Tropa','Victorias','Puntos','Actividades validadas','Pendientes'],...s.rows.map(p=>[p.name,troop(p.troop)?.name,p.wins,p.points,p.played,p.provisional])].map(row=>row.map(cell).join(',')).join('\r\n');mime='text/csv;charset=utf-8';}const url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=`cadipas-${new Date().toISOString().slice(0,10)}.${kind}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function tiebreakForm(){const x=summary(state);const candidates={patrol:x.tiedPatrols.map(p=>[p.id,p.name]),alliance:x.alliances.map(a=>[a.id,a.name]),europeos:TROOPS.filter(t=>t.alliance==='europeos').map(t=>[t.id,t.short]),muiscas:TROOPS.filter(t=>t.alliance==='muiscas').map(t=>[t.id,t.short])};open(`${head('Resolver un empate')}<p class="help">Usar solo cuando los puntajes estén empatados, después de la prueba o decisión prevista en el reglamento. Cualquier cambio posterior en resultados invalida estas decisiones.</p><form id="tie-form"><label class="field"><span>Clasificación</span><select name="type" id="tie-type">${options([['patrol','Mejor patrulla'],['europeos','Líder europeo del sábado'],['muiscas','Líder Muisca del sábado'],['alliance','Alianza ganadora del domingo']],'patrol')}</select></label><label class="field"><span>Ganador del desempate</span><select name="winner" id="tie-winner"></select></label><label class="field"><span>Prueba realizada y motivo</span><textarea name="reason" required minlength="10" maxlength="1000"></textarea></label><button class="btn primary full" ${state.closed?'disabled':''}>Registrar decisión</button></form>`);const fill=()=>$('#tie-winner').innerHTML=options(candidates[$('#tie-type').value],'');$('#tie-type').onchange=fill;fill();$('#tie-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);run(()=>save('set_decision',{type:f.get('type'),winner:f.get('winner'),reason:f.get('reason')}));};}
function cancelTournamentForm(id){const t=state.tournaments.find(t=>t.id===id);open(`${head('Anular torneo')}<p class="rule">Se conservarán los encuentros en la bitácora y el torneo quedará anulado. Su resultado final dejará de sumar. Podrás crear un torneo nuevo y volver a registrar los marcadores correctos.</p><form id="cancel-tournament-form"><label class="field"><span>Motivo</span><textarea name="reason" required minlength="10" maxlength="1000"></textarea></label><button class="btn danger full">Anular ${esc(t.name)}</button></form>`);$('#cancel-tournament-form').onsubmit=e=>{e.preventDefault();run(()=>save('cancel_tournament',{id:t.id,version:t.version,reason:new FormData(e.target).get('reason')}));};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.hasAttribute('data-close'))return close();
  if(b.hasAttribute('data-programa'))return viewProgram();
  if(b.hasAttribute('data-check-connection'))return run(async()=>{await checkConnection();toast('Supabase conectado. La base de la aplicación está disponible.');});
  if(b.dataset.tab){tab=b.dataset.tab;render();window.scrollTo(0,0);return;}
  if(b.hasAttribute('data-refresh'))return refresh();
  if(b.hasAttribute('data-logout'))return run(async()=>{try{await logout();}catch{forget();}state=null;close();loginPage();});
  if(b.dataset.day){day=b.dataset.day;block='Todos';render();return;}
  if(b.dataset.block){block=b.dataset.block;render();return;}
  if(b.dataset.kitchenFilter){kitchen.filter=b.dataset.kitchenFilter;render();return;}
  if(b.dataset.kitchenTroop)return kitchenTroop(b.dataset.kitchenTroop);
  if(b.dataset.kitchenPatrol){const prior=kitchenScores(kitchenMeal).some(x=>x.patrol===b.dataset.kitchenPatrol);return prior?kitchenReconfirm(b.dataset.kitchenPatrol):kitchenScoreForm(b.dataset.kitchenPatrol);}
  if(b.hasAttribute('data-kitchen-final'))return kitchenFinal();
  if(b.dataset.resultFilter){results.filter=b.dataset.resultFilter;render();return;}
  if(b.dataset.result)return resultForm(b.dataset.result);
  if(b.dataset.editResult){const r=state.results.find(r=>r.id===b.dataset.editResult);return resultForm(r.game,r.id);}
  if(b.hasAttribute('data-add-patrol'))return patrolForm();
  if(b.dataset.editPatrol)return patrolForm(b.dataset.editPatrol);
  if(b.dataset.tournament)return tournamentView(b.dataset.tournament);
  if(b.dataset.match)return matchForm(b.dataset.match,Number(b.dataset.round),Number(b.dataset.index));
  if(b.hasAttribute('data-rules'))return rules();
  if(b.hasAttribute('data-tiebreak'))return tiebreakForm();
  if(b.hasAttribute('data-database'))return run(()=>openDatabaseEditor({open,close,toast,onChange:async()=>{state=await snapshot();lastSync=new Date();render();}}));
  if(b.dataset.cancelTournament)return cancelTournamentForm(b.dataset.cancelTournament);
  if(b.dataset.export)return exportFile(b.dataset.export);
  if(b.dataset.reopenResult)return reopenResultForm(b.dataset.reopenResult);
  if(b.dataset.status){const r=state.results.find(r=>r.id===b.dataset.id);open(`${head(b.dataset.status==='void'?'Anular resultado':'Validar resultado')}<p class="help">${esc(gname(r.game))} · ${esc(r.label)}</p><form id="status-form"><label class="field"><span>Motivo o revisión realizada</span><textarea name="reason" required minlength="5" maxlength="500" placeholder="Ej. Marcador verificado con el responsable"></textarea></label><button class="btn primary full">Confirmar</button></form>`);$('#status-form').onsubmit=e=>{e.preventDefault();run(()=>save('result_status',{id:r.id,version:r.version,status:b.dataset.status,reason:new FormData(e.target).get('reason')}));};return;}
  if(b.hasAttribute('data-validate-all'))return validateAllForm();
  if(b.hasAttribute('data-clear-results'))return clearResultsForm();
  if(b.hasAttribute('data-close-event')){const decision=summary(state);if(!state.closed&&(!decision.bestTroop||!decision.patrolWinner))return toast('Resuelve los empates de patrulla, tropa y alianza desde Control antes de cerrar.');const pending=state.results.filter(r=>r.status==='provisional').length,unfinished=state.tournaments.filter(t=>!t.cancelled&&!t.rounds.at(-1)[0].winner).length;open(`${head(state.closed?'Reabrir evento':'Cerrar clasificación')}<p class="rule">${state.closed?'Se habilitará nuevamente el registro.':`${pending} resultados pendientes y ${unfinished} torneos sin terminar. El cierre bloquea nuevos cambios y requiere resolver los pendientes. Revisa también las oportunidades de todas las patrullas y los empates.`}</p><form id="close-form"><label class="field"><span>Motivo</span><input name="reason" required minlength="5" maxlength="500"></label><button class="btn primary full" ${!state.closed&&(pending||unfinished)?'disabled':''}>${state.closed?'Reabrir':'Confirmar cierre'}</button></form>`);$('#close-form').onsubmit=e=>{e.preventDefault();run(()=>save('set_closed',{closed:!state.closed,reason:new FormData(e.target).get('reason')}));};}
});
document.addEventListener('input',e=>{if(e.target.id==='game-search'){search=e.target.value;const pos=e.target.selectionStart;render();const el=$('#game-search');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('contextmenu',e=>{const b=e.target.closest('.score-adjust');if(!b)return;e.preventDefault();adjustPointsForm(b.dataset.adjustTarget,b.dataset.adjustId);});
let scorePress;
document.addEventListener('touchstart',e=>{const b=e.target.closest('.score-adjust');if(!b)return;scorePress=setTimeout(()=>{scorePress=null;adjustPointsForm(b.dataset.adjustTarget,b.dataset.adjustId);},650);},{passive:true});
for(const event of ['touchend','touchcancel','touchmove'])document.addEventListener(event,()=>{if(scorePress){clearTimeout(scorePress);scorePress=null;}},{passive:true});
modal.addEventListener('cancel',()=>{formDirty=false;});
modal.addEventListener('close',()=>{modal.onkeydown=null;});
window.addEventListener('online',()=>refresh(false));window.addEventListener('offline',()=>toast('Sin conexión. Conserva el formulario; espera conexión para guardar.'));
window.addEventListener('beforeunload',e=>{if(formDirty){e.preventDefault();e.returnValue='';}});
if(getSession()&&configured)boot();else loginPage();



